	return "<color=yellow>L\214nh B\181i Gi\184p S\220<color>: b\233 chi\170u t\249 \174\184nh lu\169n phi\170n (chi\170u \174o\182n \174ao hay tr\173\234ng \174ao t\249 l\228c theo \174ao \174ang c\199m). Hi\214n t\185i: <color=green>" .. PTLB_DescGS(GetTask(PTLB_T_GS)) .. "<color>. Ch\228n b\233 l\181 t\249 b\203t t\249 \174\184nh; Alt+A c\242ng b\203t ho\198c t\190t."
end

-- attack skills of the given blades replace the attack part; the chosen auras stay
function PTLBGS_SetBl(e1, e2)
	PTLB_Load()
	local v = GetTask(PTLB_T_GS)
	local i = 1
	while i <= PTLB_GS.n do
		local s = PTLB_GS[i]
		if s.kind == 1 then
			if s.el == e1 or s.el == e2 then v = PTLB_With(PTLB_GS, v, s.id) else v = PTLB_Without(PTLB_GS, v, s.id) end
		end
		i = i + 1
	end
	PTLB_Apply(PTLB_T_GS, v)
	local n, a = PTLB_Count(PTLB_GS, v)
	Msg2Player("L\214nh B\181i Gi\184p S\220: b\233 chi\170u " .. PTLB_DescGS(v) .. " - t\249 \174\184nh lu\169n phi\170n " .. a .. " chi\170u \174\184nh \174\183 h\228c h\238p v\237i \174ao \174ang c\199m.")
	if a == 0 then Msg2Player("B\185n ch\173a h\228c chi\170u \174\184nh n\181o trong b\233: t\249 \174\184nh t\185m d\239ng chi\170u \174ang g\184n \235 ph\221m.") end
	PTLBGS_After()
end

function PTLBGS_Pre1() PTLBGS_SetBl(1, 2) end
function PTLBGS_Pre2() PTLBGS_SetBl(1, 0) end
function PTLBGS_Pre3() PTLBGS_SetBl(2, 0) end

function PTLBGS_Off()
	PTLB_Apply(PTLB_T_GS, 0)
	Msg2Player("L\214nh B\181i Gi\184p S\220: t\249 \174\184nh d\239ng chi\170u \174ang g\184n \235 tay tr\184i, tay ph\182i v\181 ph\221m Q W E / A S D / Z X C.")
	PTLBGS_After()
end

function PTLBGS_Start()
	PTLB_StartAuto("L\214nh B\181i Gi\184p S\220")
end

function PTLBGS_Stop()
	PTLB_StopAuto("L\214nh B\181i Gi\184p S\220")
end

-- after a set was chosen: start the auto fight (menu closed), or show the menu again (option off)
function PTLBGS_After()
	if GetTask(PTLB_T_PREF) == 0 then
		PTLB_StartAuto("L\214nh B\181i Gi\184p S\220")
	else
		PTLBGS_Main()
	end
end

function PTLBGS_Main()
	PTLB_Load()
	local o = {}
	o[1] = "B\190t \174\199u t\249 \174\233ng \174\184nh/PTLBGS_Start"
	o[2] = "D\245ng t\249 \174\233ng \174\184nh/PTLBGS_Stop"
	o[3] = "B\233 t\202t c\182 chi\170u \174\184nh (m\198c \174\222nh)/PTLBGS_Pre1"
	o[4] = "B\233 \174o\182n \174ao/PTLBGS_Pre2"
	o[5] = "Ch\228n t\245ng chi\170u (b\203t, t\190t).../PTLBGS_Groups"
	o[6] = "B\233 kh\184c, t\239y ch\228n, n\169ng c\202p k\252 n\168ng.../PTLBGS_More"
	o[7] = "\167\227ng/PTLB_No"
	PTLB_Say(PTLBGS_Title(), o)
end

function PTLBGS_Groups()
	PTLB_Load()
	local v = GetTask(PTLB_T_GS)
	local o = {}
	o[1] = "Chi\170u \174o\182n \174ao" .. " (" .. PTLB_GroupCount(PTLB_GS, v, 1) .. " \174ang b\203t)" .. "/PTLBGS_G1"
	o[2] = "Chi\170u tr\173\234ng \174ao" .. " (" .. PTLB_GroupCount(PTLB_GS, v, 2) .. " \174ang b\203t)" .. "/PTLBGS_G2"
	o[3] = "H\181o quang" .. " (" .. PTLB_GroupCount(PTLB_GS, v, 3) .. " \174ang b\203t)" .. "/PTLBGS_G3"
	o[4] = "Quay l\185i/PTLBGS_Main"
	o[5] = "\167\227ng/PTLB_No"
	PTLB_Say("<color=yellow>L\214nh B\181i Gi\184p S\220<color>: ch\228n nh\227m chi\170u, r\229i b\202m t\245ng chi\170u \174\211 b\203t ho\198c t\190t. [B\203T] = t\249 \174\184nh d\239ng chi\170u \174\227. Ch\216 hi\214n chi\170u \174\183 h\228c.", o)
end

function PTLBGS_Group(g)
	PTLB_Load()
	local l = PTLB_GroupList(PTLB_GS, g)
	local v = GetTask(PTLB_T_GS)
	local names = { "Chi\170u \174o\182n \174ao", "Chi\170u tr\173\234ng \174ao", "H\181o quang" }
	if getn(l) == 0 then
		Say("<color=yellow>L\214nh B\181i Gi\184p S\220<color>: b\185n ch\173a h\228c chi\170u n\181o c\241a nh\227m " .. names[g] .. ".", 2, "Quay l\185i/PTLBGS_Groups", "\167\227ng/PTLB_No")
		return
	end
	local o = {}
	local n = 0
	local i = 1
	while l[i] do
		local s = PTLB_GS[l[i]]
		local m = "[t\190t] "
		if PTLB_Has(PTLB_GS, v, s.id) then m = "[B\203T] " end
		n = n + 1
		o[n] = m .. s.nm .. "/PTLBGS_T" .. l[i]
		i = i + 1
	end
	if n <= 5 then n = n + 1 o[n] = "Xong, b\190t \174\199u t\249 \174\233ng \174\184nh/PTLBGS_Start" end
	n = n + 1 o[n] = "Quay l\185i/PTLBGS_Groups"
	if n < 7 then n = n + 1 o[n] = "\167\227ng/PTLB_No" end
	PTLB_Say("<color=yellow>L\214nh B\181i Gi\184p S\220<color>: nh\227m " .. names[g] .. " - b\202m m\233t chi\170u \174\211 b\203t ho\198c t\190t (\174ang b\203t " .. PTLB_GroupCount(PTLB_GS, v, g) .. ").", o)
end

function PTLBGS_G1() PTLBGS_Group(1) end
function PTLBGS_G2() PTLBGS_Group(2) end
function PTLBGS_G3() PTLBGS_Group(3) end

-- toggle skill k of the table, then show its group page again
function PTLBGS_Toggle(k)
	PTLB_Load()
	local s = PTLB_GS[k]
	if not s or not PTLB_Learnt(s.id) then return end
	local v = GetTask(PTLB_T_GS)
	local on = nil
	if PTLB_Has(PTLB_GS, v, s.id) then v = PTLB_Without(PTLB_GS, v, s.id) else v = PTLB_With(PTLB_GS, v, s.id) on = 1 end
	local n, a = PTLB_Count(PTLB_GS, v)
	if n == 0 then v = 0 end
	PTLB_Apply(PTLB_T_GS, v)
	if on then Msg2Player("L\214nh B\181i Gi\184p S\220: b\203t " .. s.nm) else Msg2Player("L\214nh B\181i Gi\184p S\220: t\190t " .. s.nm) end
	PTLBGS_Group(s.grp)
end

