function PTLBGS_UpOne(id)
	local s = PTLB_FindPS(0, id)
	if not s then return end
	if PTLB_Lv(id) >= s.mx then
		Msg2Player("L\214nh B\181i Gi\184p S\220: " .. s.nm .. " \174\183 \235 c\202p t\232i \174a " .. s.mx .. ".")
		PTLBGS_UpShow(id)
		return
	end
	Say("<color=yellow>L\214nh B\181i Gi\184p S\220<color>: n\169ng " .. s.nm .. " l\170n c\202p t\232i \174a " .. s.mx .. "?", 2, "\167\229ng \253/PTLBGS_Y" .. id, "Kh\171ng/PTLBGS_Up")
end

function PTLBGS_UpOk(id)
	local s = PTLB_FindPS(0, id)
	if not s then return end
	if PTLB_MaxOne(s) > 0 then
		Msg2Player("L\214nh B\181i Gi\184p S\220: \174\183 n\169ng " .. s.nm .. " l\170n c\202p " .. s.mx .. ".")
	else
		Msg2Player("L\214nh B\181i Gi\184p S\220: kh\171ng n\169ng \174\173\238c " .. s.nm .. ".")
	end
	PTLBGS_UpShow(id)
end

-- show the upgrade page holding skill id
function PTLBGS_UpShow(id)
	local s, pos = PTLB_FindPS(0, id)
	if pos < 1 then pos = 1 end
	PTLBGS_UpPage(floor((pos - 1) / 5) + 1)
end

